'use strict';
if (nexus.input.trigger === 'config-repair') {
function proposeRepair(input) {
  const rule = input.rule, root = input.document, context = input.context;
  const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const select = (value, path) => path.reduce((node, key) => node == null ? undefined : node[key], value);
  if (!object(root)) return null;
  if (rule.skipWhen && select(root, rule.skipWhen.selector) === rule.skipWhen.equals) return null;
  let selector = rule.selector.slice(), previous = select(root, selector), value;
  if (rule.resourceId === 'config:instances/{instance}.json' && previous === undefined) {
    const settings = nexus.readConfig('extra:0');
    const selected = settings?.DefaultConfig;
    const file = typeof selected === 'string' && selected !== 'Default' && /^[A-Za-z0-9_-]+$/.test(selected)
      ? 'mfa_' + selected + '.json' : 'config.json';
    const shared = nexus.readConfig('config:' + file) || nexus.readConfig('config:config.json');
    const field = selector[0];
    previous = shared?.['Instance.' + context.configInputValue + '.' + field]
      ?? shared?.['Instance.default.' + field] ?? shared?.[field];
  }
  if (rule.kind === 'mxu_tasks' || rule.kind === 'mxu_preactions') {
    const id = root.settings?.autoStartInstanceId;
    const instances = Array.isArray(root.instances) ? root.instances.filter(i => i && i.id === id) : [];
    if (typeof id !== 'string' || !id || instances.length !== 1) return null;
    const field = rule.kind === 'mxu_tasks' ? 'tasks' : 'preActions';
    selector = ['instances', {by:'id', value:id}, field];
    previous = instances[0][field];
    if (rule.kind === 'mxu_preactions' && previous === undefined)
      previous = instances[0].preAction ? [instances[0].preAction] : [];
  }
  if (rule.kind === 'mxu_preactions') {
    if (!context.pc || !context.gamePath || !Array.isArray(previous) || previous.length > 1023 || !previous.every(object)) return null;
    value = JSON.parse(JSON.stringify(previous));
    if (!value.length) value.push({id:'nxp-start-game', args:context.gameArguments, skipIfRunning:true, useCmd:false});
    const first = value[0];
    if (first.program !== undefined && typeof first.program !== 'string') return null;
    first.id ||= 'nxp-start-game';
    first.enabled = true; first.program = context.gamePath; first.waitForExit = false;
    if (!Object.hasOwn(first, 'args')) first.args = context.gameArguments;
  } else if (rule.kind === 'mxu_tasks' || rule.kind === 'mfa_tasks') {
    if (!Array.isArray(previous) || previous.length > 1023 || !previous.every(object)) return null;
    value = repairTasks(JSON.parse(JSON.stringify(previous)), rule.kind === 'mxu_tasks');
  } else if (rule.kind === 'bind_game_path') {
    if (!context.pc || !context.gamePath || previous !== undefined && typeof previous !== 'string') return null;
    const normalize = p => p.trim().replace(/^"|"$/g, '').replace(/\//g, '\\').replace(/\\+$/, '').toLowerCase();
    if (typeof previous === 'string' && normalize(previous) === normalize(context.gamePath)) return null;
    value = context.gamePath;
  } else if (rule.kind === 'enable_boolean') {
    if (previous !== undefined && previous !== false) return null;
    value = true;
  } else {
    if (rule.resourceId === 'config:instances/{instance}.json' && selector[0] === 'BeforeTask') {
      if (!context.pc || !context.gamePath) return null;
      if (previous === undefined) previous = 'None';
    }
    if (typeof previous !== 'string') return null;
    if (rule.kind === 'replace_enum' ? !rule.fromValues.includes(previous) : rule.fromValues.includes(previous)) return null;
    value = rule.toValue;
  }
  return JSON.stringify(previous) === JSON.stringify(value) ? null : {selector, value};
}

function repairTasks(tasks, mxu) {
  const nameKey = mxu ? 'taskName' : 'entry', enabledKey = mxu ? 'enabled' : 'default_check';
  const powerName = mxu ? '__MXU_POWER__' : 'ComputerOperationAction';
  for (const task of tasks) {
    if (task[nameKey] !== powerName) continue;
    task[enabledKey] = false;
    if (mxu && task.enabledByController)
      for (const key of Object.keys(task.enabledByController)) task.enabledByController[key] = false;
  }
  return tasks;
}

nexus.proposeRepair(proposeRepair(nexus.input));
} else if (nexus.input.trigger === "config-edit-commit") {

} else {
"use strict";

const selected = String(nexus.input.configInputValue || "").trim();
if (!/^\d{2}$/.test(selected)) {
  throw new Error("实例序号必须是两位数字");
}

const extra = nexus.input.extras && nexus.input.extras[0];
const file = extra && extra.files && extra.files[0] && extra.files[0].path;
if (!file) {
  throw new Error("one_dragon.yml 工作副本不存在");
}
const source = nexus.readFile("@extra0/" + file);
if (source === null) {
  throw new Error("无法读取 one_dragon.yml 工作副本");
}

const hasBom = source.startsWith("\uFEFF");
const body = hasBom ? source.slice(1) : source;
const newline = body.includes("\r\n") ? "\r\n" : "\n";
const hasFinalNewline = body.endsWith("\n");
const lines = body.split(/\r?\n/);
if (hasFinalNewline && lines[lines.length - 1] === "") {
  lines.pop();
}

const sectionPattern = /^(\s*)instance_list\s*:\s*(?:#.*)?$/;
let sectionStart = -1;
let sectionIndent = 0;
for (let index = 0; index < lines.length; index += 1) {
  if (sectionPattern.test(lines[index])) {
    if (sectionStart >= 0) {
      throw new Error("one_dragon.yml 存在重复 instance_list");
    }
    sectionStart = index;
    sectionIndent = lines[index].match(sectionPattern)[1].length;
  }
}
if (sectionStart < 0) {
  throw new Error("one_dragon.yml 缺少 instance_list");
}

let firstContent = sectionStart + 1;
while (firstContent < lines.length && /^\s*(?:#.*)?$/.test(lines[firstContent])) {
  firstContent += 1;
}
if (firstContent >= lines.length) {
  throw new Error("instance_list 为空");
}
const firstMatch = lines[firstContent].match(/^(\s*)-\s*(.*)$/);
if (!firstMatch || firstMatch[1].length < sectionIndent) {
  throw new Error("instance_list 格式无效");
}
const itemIndent = firstMatch[1].length;

let sectionEnd = lines.length;
for (let index = firstContent; index < lines.length; index += 1) {
  if (/^\s*(?:#.*)?$/.test(lines[index])) {
    continue;
  }
  const lineMatch = lines[index].match(/^(\s*)-\s*(.*)$/);
  const indent = lines[index].match(/^\s*/)[0].length;
  if (indent < itemIndent
      || (indent === itemIndent && !lineMatch)) {
    sectionEnd = index;
    break;
  }
}

const itemStarts = [];
for (let index = firstContent; index < sectionEnd; index += 1) {
  const match = lines[index].match(/^(\s*)-\s*(.*)$/);
  if (match && match[1].length === itemIndent) {
    itemStarts.push(index);
  } else if (!/^\s*(?:#.*)?$/.test(lines[index])
      && lines[index].match(/^\s*/)[0].length < itemIndent) {
    throw new Error("instance_list 条目缩进不一致");
  }
}
if (itemStarts.length === 0) {
  throw new Error("instance_list 没有有效条目");
}

const entries = [];
for (let index = 0; index < itemStarts.length; index += 1) {
  const start = itemStarts[index];
  const end = index + 1 < itemStarts.length ? itemStarts[index + 1] : sectionEnd;
  const block = lines.slice(start, end);
  let idxValue = null;
  let idxCount = 0;
  let idxIndent = itemIndent + 2;
  const inlineIdx = block[0].match(/^\s*-\s*idx\s*:\s*(.*?)\s*(?:#.*)?$/);
  if (inlineIdx) {
    idxCount += 1;
    idxValue = normalizeInstanceIndex(inlineIdx[1]);
  }
  for (const line of block.slice(1)) {
    const match = line.match(/^(\s*)idx\s*:\s*(.*?)\s*(?:#.*)?$/);
    if (!match) {
      continue;
    }
    idxCount += 1;
    idxIndent = match[1].length;
    idxValue = normalizeInstanceIndex(match[2]);
  }
  if (idxCount !== 1 || !/^\d{2}$/.test(idxValue || "")) {
    throw new Error("instance_list 存在缺失或重复的 idx");
  }
  entries.push({ start, end, block, idx: idxValue, idxIndent });
}

const selectedEntries = entries.filter(entry => entry.idx === selected);
if (selectedEntries.length !== 1) {
  throw new Error(selectedEntries.length === 0
    ? "instance_list 中找不到选定实例"
    : "instance_list 中存在重复的选定实例");
}

const selectedEntry = selectedEntries[0];
const fields = new Set();
for (let index = 1; index < selectedEntry.block.length; index += 1) {
  const line = selectedEntry.block[index];
  const activeMatch = line.match(/^(\s*)(active|active_in_od)\s*:\s*.*$/);
  if (!activeMatch) {
    continue;
  }
  const name = activeMatch[2];
  fields.add(name);
  selectedEntry.block[index] = activeMatch[1] + name + ": true";
}
if (!fields.has("active")) {
  selectedEntry.block.push(" ".repeat(selectedEntry.idxIndent) + "active: true");
}
if (!fields.has("active_in_od")) {
  selectedEntry.block.push(" ".repeat(selectedEntry.idxIndent) + "active_in_od: true");
}

const outputLines = lines
  .slice(0, firstContent)
  .concat(selectedEntry.block)
  .concat(lines.slice(sectionEnd));
// This is the isolated binding work copy. Explicitly select CURRENT as well as
// retaining only the selected instance; never persist an all-account launch mode.
let runModeSeen = false;
for (let index = 0; index < outputLines.length; index += 1) {
  const match = outputLines[index].match(/^(\s*)instance_run\s*:(.*)$/);
  if (!match || match[1].length !== sectionIndent) continue;
  if (runModeSeen) throw new Error("one_dragon.yml 存在重复 instance_run");
  runModeSeen = true;
  const value = match[2].match(/^\s*(?:全部实例|仅运行当前|'全部实例'|'仅运行当前'|"全部实例"|"仅运行当前")\s*(#.*)?$/);
  if (!value) throw new Error("one_dragon.yml instance_run 格式无效");
  outputLines[index] = match[1] + "instance_run: 仅运行当前" + (value[1] ? " " + value[1] : "");
}
if (!runModeSeen) outputLines.push(" ".repeat(sectionIndent) + "instance_run: 仅运行当前");
const output = (hasBom ? "\uFEFF" : "") + outputLines.join(newline) + (hasFinalNewline ? newline : "");
if (!nexus.writeFile("@extra0/" + file, output)) {
  throw new Error("无法写回 one_dragon.yml 工作副本");
}

function normalizeInstanceIndex(raw) {
  const value = String(raw || "").replace(/^['"]|['"]$/g, "");
  return /^\d{1,2}$/.test(value) ? value.padStart(2, "0") : value;
}

}
